sys_script_include.script:
var MSS_Custody_Retry_Outbound = Class.create();
MSS_Custody_Retry_Outbound.prototype = {
    initialize: function() {
    },

	checkEnvironment: function() {
		var interval = gs.getProperty("x_hsb11_mss_custod.retry_interval_environment_check");
		var uriProp = gs.getProperty("x_hsb11_mss_custod.eventCustodyonDemand_uri"); 
		var grOutboundHttpLog = new GlideRecord("sys_outbound_http_log");
		var errorCodes = gs.getProperty('x_hsb11_mss_custod.mss_custody_onDemand_error_codes');
		grOutboundHttpLog.addQuery("response_status","IN",errorCodes);
		grOutboundHttpLog.addEncodedQuery(interval);
		grOutboundHttpLog.addQuery("url",uriProp);
		grOutboundHttpLog.query();
		if(grOutboundHttpLog.hasNext()){
			return false;
		}else{
			return true;
		}
	},

	retry: function(){
		var retryCount = gs.getProperty("x_hsb11_mss_custod.mss_custody_outbound_retry_count");
		var grMssCustodyOutbound = new GlideRecord("x_hsb11_mss_custod_mss_custody_unity_ondemand_staging");
		grMssCustodyOutbound.addQuery("state","Error");
		grMssCustodyOutbound.addQuery("retry_count","<",retryCount);
		grMssCustodyOutbound.addEncodedQuery("sys_created_on>=javascript:gs.beginningOfYesterday()");
		grMssCustodyOutbound.query();
		while (grMssCustodyOutbound.next()){
			grMssCustodyOutbound.state="Ready to be sent";
			grMssCustodyOutbound.refresh_start_time= new GlideDateTime();
			grMssCustodyOutbound.refresh_end_time='';
			grMssCustodyOutbound.update();
		}
	},

    type: 'MSS_Custody_Retry_Outbound'
};
